# ------------------------------------------------------------- optimizer
def fit(self, psi0, tol=1e-9, maxiter=300):
    """Trust-region style REML fit; expected information stands in for the
    Hessian (requirement R11), with backtracking and a Nelder-Mead polish."""
    psi = np.asarray(psi0, float).copy()
    cur = self.reml(psi)
    if cur is None:
        raise ValueError("start is not in the extended parameter set")
    f = -cur["loglik"]
    for _ in range(maxiter):
        g = -cur["score"]
        if np.max(np.abs(g)) < tol:
            break
        H = cur["info"]
        step = None
        scale = max(1.0, np.trace(H) / R)
        for lam in (0.0, 1e-10, 1e-8, 1e-6, 1e-4, 1e-2, 1.0):
            try:
                L = np.linalg.cholesky(H + lam * scale * np.eye(R))
            except np.linalg.LinAlgError:
                continue
            d = np.linalg.solve(L.T, np.linalg.solve(L, -g))
            if np.all(np.isfinite(d)):
                step = d
                break
        if step is None:
            step = -g
        accepted = False
        t = 1.0
        for _ in range(40):
            cand = psi + t * step
            out = self.reml(cand)
            if out is not None and -out["loglik"] <= f - 1e-14 * abs(f):
                psi, cur, f = cand, out, -out["loglik"]
                accepted = True
                break
            t *= 0.5
        if not accepted:
            break
    try:
        from scipy.optimize import minimize

        def obj(p):
            out = self.reml(p)
            return 1e12 if out is None else -out["loglik"]

        res = minimize(obj, psi, method="Nelder-Mead",
                       options=dict(xatol=1e-11, fatol=1e-13, maxiter=600))
        out = self.reml(res.x)
        if out is not None and -out["loglik"] <= f + 1e-9:
            psi, cur, f = res.x, out, -out["loglik"]
    except Exception:
        pass
    return psi, cur
